// This benchmark exercises model/storage code, not a running Minecraft server.
tasks.register('soilScaleBenchmark', JavaExec) {
    group = 'verification'
    description = 'Model/storage microbenchmark; not a live-server TPS test.'
    dependsOn tasks.named('testClasses')
    classpath = sourceSets.test.runtimeClasspath
    mainClass = 'com.foundations.soil.SoilScaleBenchmark'
    maxHeapSize = '1500m'
    args layout.buildDirectory.file('reports/soil-scale-benchmark.json').get().asFile.absolutePath
    if (modRuntimeTests) {
        enabled = false
    }
}

